const artist = $json.artist;
const album = $json.albumname;

const platforms = [
  { key: 'spotify', q: `${artist} - ${album} spotify` },
  { key: 'tidal', q: `${artist} - ${album} tidal` },
  { key: 'apple', q: `${artist} - ${album} apple music` },
  { key: 'qobuz', q: `${artist} - ${album} qobuz` },
];

return platforms.map(p => ({ json: { artist, album, platform: p.key, query: p.q } }));

