function pickFirstMatchingUrl(platform, results) {
  const domains = {
    spotify: [/open\.spotify\.com\//i, /spotify\.com\//i],
    tidal: [/tidal\.com\//i],
    apple: [/music\.apple\.com\//i, /itunes\.apple\.com\//i, /embed\.music\.apple\.com\//i],
    qobuz: [/qobuz\.com\//i]
  };

  const regs = domains[platform] || [];
  if (!Array.isArray(results)) return null;

  for (const r of results) {
    const url = r && r.url;
    if (!url) continue;
    if (regs.some(rx => rx.test(url))) return url;
  }
  return null;
}

const platform = $json.platform;
const results = ($json.results || []);
const link = pickFirstMatchingUrl(platform, results);

return [{ json: { platform, query: $json.query, link: link || '' } }];

const items = $items();
const map = {};
for (const it of items) {
  const j = it.json;
  if (j && j.platform) map[j.platform] = j.link || '';
}

const order = ['tidal', 'apple', 'spotify', 'qobuz'];
const lines = order.map(p => `${p}: ${map[p] || ''}`);
return [{ json: { markdown: lines.join('\n') } }];
